"""Regenerate primary matrices from colour-science 0.4.6 (development only)."""
import functools
from pathlib import Path
import colour
p=Path(__file__).resolve().parents[2]/'crates/spektrafilm-math/src/color_registry.rs'
rows=[]
for name,s in colour.RGB_COLOURSPACES.items():
 enc=s.cctf_encoding
 if isinstance(enc,functools.partial) and 'exponent' in enc.keywords:
  curve=f'Transfer::Gamma({1/enc.keywords["exponent"]!r})'
 else:
  m={'log_encoding_ACESproxy':'Acesproxy','eotf_inverse_DCDM':'Dcdm','log_encoding_REDLogFilm':'Cineon','log_encoding_ERIMMRGB':'Erimm','log_encoding_FilmLightTLog':'Tlog','log_encoding_Protune':'Protune','cctf_encoding_RIMMRGB':'Rimm','log_encoding_SLog2':'Slog2','oetf_SMPTE240M':'Smpte240','linear_function':'Linear','eotf_inverse_sRGB':'Srgb','cctf_encoding_ROMMRGB':'ProPhoto','oetf_BT2020':'Bt709','oetf_BT709':'Bt709','log_encoding_FLog':'Flog','log_encoding_Log3G10':'Log3g10','log_encoding_DJIDLog':'Dlog','log_encoding_NLog':'Nlog','log_encoding_ACEScc':'Acescc','log_encoding_ACEScct':'Acescct','log_encoding_VLog':'Vlog','log_encoding_SLog3':'Slog3','log_encoding_ARRILogC3':'Logc3','log_encoding_ARRILogC4':'Logc4','oetf_DaVinciIntermediate':'DaVinci','oetf_BlackmagicFilmGeneration5':'Blackmagic5'}
  curve='Transfer::'+('Lab' if name=='ECI RGB v2' else m.get(getattr(enc,'__name__',''),'Unsupported'))
 rows.append('ColorSpace { name: '+__import__('json').dumps(name)+', to_xyz: '+repr(s.matrix_RGB_to_XYZ.tolist())+', from_xyz: '+repr(s.matrix_XYZ_to_RGB.tolist())+', white: '+repr(colour.xy_to_XYZ(s.whitepoint).tolist())+', transfer: '+curve+' },')
p.write_text('// Generated by scripts/reference/generate_color_spaces.py using colour-science 0.4.6.\nuse super::{ColorSpace, Transfer};\npub static SPACES: &[ColorSpace] = &[\n'+ '\n'.join(rows)+'\n];\n')
